def is_valid_exchange(area, exchange):
    """Validates the exchange code with enhanced logic"""
    if (
        exchange.startswith("0") or
        exchange.startswith("1") or
        exchange in n11_codes or
        exchange == area
    ):
        return False
    return True


def is_valid_line_number(line):
    # Reject common test patterns
    ascending = ['1234', '2345', '3456', '4567']
    descending = ['9876', '8765', '7654', '6543']

    if line in ascending or line in descending:
        return False

    # Reject repeated digit patterns like 0000, 1111, ..., 9999
    if len(set(line)) == 1:
        return False

    # Reject sequential ascending like 1234, 3456, etc.
    if re.match(r'(?:0123|1234|2345|3456|4567|5678|6789)', line):
        return False

    # Reject sequential descending like 9876, 8765, etc.
    if re.match(r'(?:9876|8765|7654|6543|5432|4321|3210)', line):
        return False

    return True

def generate_phone_number():
    area =  str(random.choice(area_codes))                        #str(random.choice(area_codes))

    '''
    while True:
        central = str(random.randint(200, 999))
        if is_valid_exchange(area, central):
            break
    '''
    central = random.choice(valid_nxx)
    # Generate a valid line number
    while True:
        line = str(random.randint(0, 9999)).zfill(4)
        if is_valid_line_number(line):
            break

    num = f"{area}{central}{line}"
    valid = False
    try:
        parsed = phonenumbers.parse(num, "US")
        valid = phonenumbers.is_valid_number(parsed)
        region = phonenumbers.region_code_for_number(parsed)
        #print(f"{num} → valid: {valid}, country: {region}")
        print(f"generated number : {num} ")
        valid = True
    except:
        print(f"{num} → unparseable")

    if valid:
        return f"+1{area}{central}{line}"

    else:
        return -1




